use vstd::prelude::*;

verus! {

fn replace_last_element(first: &Vec<i32>, second: &Vec<i32>) -> (replaced_list: Vec<i32>)
    requires
        first.len() > 0,
    ensures
        replaced_list.len() == first.len() - 1 + second.len(),
        forall|i: int| 0 <= i < first.len() - 1 ==> 
            replaced_list[i] == first[i],
        forall|i: int| 0 <= i < second.len() ==> 
            replaced_list[first.len() - 1 + i] == second[i],
{
    // Since first is non-empty, safe to slice up to first.len() - 1
    let mut replaced_list = Vec::with_capacity(first.len() - 1 + second.len());
    
    replaced_list.extend_from_slice(&first[..first.len() - 1]);
    assert(replaced_list.len() == first.len() - 1);
    assert(forall|i: int| 0 <= i < replaced_list.len() ==> 
        replaced_list[i] == first[i]);
    
    replaced_list.extend_from_slice(&second);
    assert(replaced_list.len() == first.len() - 1 + second.len());
    
    (replaced_list)
}

} // verus!